fun findSecondLargestNumber(input: List<Int>): Int {
    val distinct = input.distinct().sortedDescending()
    return if (distinct.size >= 2) distinct[1] else distinct.firstOrNull() ?: Int.MIN_VALUE

}

fun findSecondLargestNumber(input: List<Int>): Int {
    var largest = Int.MIN_VALUE
    var secondLargest = Int.MIN_VALUE
    for (value in input) {
        if (value > largest) {
            secondLargest = largest
            largest = value
        } else if (value > secondLargest && value != largest) {
            secondLargest = value
        }
    }
    return secondLargest

}

fun findSecondLargestNumber(input: List<Int>): Int {
    return input.asSequence().sortedDescending().distinct().drop(1).firstOrNull() ?: Int.MIN_VALUE
}

